import React, { useState } from 'react';
import { SERVICES } from '../Data/mockData';
import * as LucideIcons from 'lucide-react';

const {
  Compass,
  Wrench,
  BookOpen,
  Briefcase,
  Cpu,
  GraduationCap,
  LayoutDashboard,
  PhoneCall,
  ArrowRight,
  Star,
  ChevronLeft,
  ChevronRight
} = LucideIcons;

const TESTIMONIALS = [
  { name: 'Rahul Sharma', role: 'B.Tech CSE, Placed at TCS Digital', quote: 'The ₹49 career guidance session gave me an exact roadmap. The 13-module AI course solidified my placement preparation.' },
  { name: 'Sneha Reddy', role: 'M.Tech AI Student', quote: 'Obtained IEEE source code and documentation for my final semester. Faculty accepted the project effortlessly!' },
  { name: 'Karthik Varma', role: 'Data Analyst Intern', quote: 'Hands-on live workshops for ₹19 are unmatched. Truly transformative quality for students.' }
];

export default function Home({ setActiveScreen, onOpenGuidanceBooking }) {
  const [currentTestimonial, setCurrentTestimonial] = useState(0);

  const prevTestimonial = () => {
    setCurrentTestimonial((prev) => (prev === 0 ? TESTIMONIALS.length - 1 : prev - 1));
  };

  const nextTestimonial = () => {
    setCurrentTestimonial((prev) => (prev === TESTIMONIALS.length - 1 ? 0 : prev + 1));
  };

  return (
    <div className="space-y-24 pb-20">
      {/* Hero Section */}
      <section className="relative overflow-hidden pt-12 pb-20 bg-gradient-to-b from-slate-900 via-slate-900 to-slate-950">
        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center space-y-8">
          <div className="inline-flex items-center space-x-2 bg-slate-800/80 border border-slate-700/80 px-4 py-1.5 rounded-full text-xs font-semibold uppercase tracking-wider text-emerald-400">
            <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
            <span>Next-Gen EdTech Ecosystem</span>
          </div>

          <h1 className="text-4xl sm:text-6xl lg:text-7xl font-extrabold text-white tracking-tight">
            Wisdom. Knowledge. <span className="bg-gradient-to-r from-violet-400 via-indigo-300 to-emerald-400 bg-clip-text text-transparent">Success.</span>
          </h1>

          <p className="max-w-2xl mx-auto text-lg sm:text-xl text-slate-300 font-normal leading-relaxed">
            Accelerate your engineering journey with live mentorship, specialized workshops, real-time IEEE projects, and high-impact certified internships.
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 pt-4">
            <button
              onClick={onOpenGuidanceBooking}
              className="w-full sm:w-auto px-8 py-4 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white font-semibold text-lg shadow-xl shadow-violet-700/30 transition-all transform hover:-translate-y-0.5 active:translate-y-0"
            >
              Book Your Slot
            </button>
            <button
              onClick={() => setActiveScreen('courses')}
              className="w-full sm:w-auto px-8 py-4 rounded-xl bg-slate-800/90 hover:bg-slate-800 border border-slate-700 text-white font-semibold text-lg transition-all flex items-center justify-center space-x-2"
            >
              <span>Explore Courses</span>
              <ArrowRight className="w-5 h-5 text-emerald-400" />
            </button>
          </div>

          {/* Quick Stats */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 max-w-4xl mx-auto pt-12 border-t border-slate-800/80">
            <div className="bg-slate-900/60 border border-slate-800 p-6 rounded-2xl">
              <p className="text-3xl font-bold text-white mb-1">10k+ Students</p>
              <p className="text-sm text-slate-400">Mentored & Placed Across MNCs</p>
            </div>
            <div className="bg-slate-900/60 border border-slate-800 p-6 rounded-2xl">
              <p className="text-3xl font-bold text-emerald-400 mb-1">98% Success Rate</p>
              <p className="text-sm text-slate-400">Project Approval & Placement Boost</p>
            </div>
            <div className="bg-slate-900/60 border border-slate-800 p-6 rounded-2xl">
              <p className="text-3xl font-bold text-violet-400 mb-1">Industry Mentors</p>
              <p className="text-sm text-slate-400">Tier-1 Senior Engineers</p>
            </div>
          </div>
        </div>
      </section>

      {/* Services Grid (8 Key Offerings) */}
      <section className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center space-y-3 mb-16">
          <h2 className="text-3xl sm:text-4xl font-bold text-white">Services Grid Cards (8 Key Offerings)</h2>
          <p className="text-slate-400 max-w-xl mx-auto">Explore targeted programs tailored for engineering and professional growth.</p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {SERVICES.map((srv) => {
            const IconComponent = LucideIcons[srv.icon] || BookOpen || 'div';
            return (
              <div
                key={srv.id}
                onClick={() => {
                  if (srv.id === 'guidance') setActiveScreen('guidance');
                  else if (srv.id === 'workshops') setActiveScreen('workshops');
                  else if (srv.id === 'courses') setActiveScreen('courses');
                  else if (srv.id === 'internships') setActiveScreen('internships');
                  else if (srv.id === 'btech-projects') setActiveScreen('btech-projects');
                  else if (srv.id === 'mtech-projects') setActiveScreen('mtech-projects');
                  else if (srv.id === 'dashboard') setActiveScreen('dashboard');
                  else if (srv.id === 'contact') setActiveScreen('contact');
                }}
                className="group relative bg-slate-900/80 border border-slate-800 hover:border-violet-500/50 rounded-2xl p-6 transition-all duration-300 hover:-translate-y-1.5 cursor-pointer shadow-lg hover:shadow-violet-600/10 flex flex-col justify-between"
              >
                <div>
                  <div className={`w-12 h-12 rounded-xl bg-gradient-to-r ${srv.color} flex items-center justify-center text-white mb-5 shadow-md`}>
                    {IconComponent && typeof IconComponent === 'function' ? (
                      <IconComponent className="w-6 h-6" />
                    ) : (
                      <span className="font-bold text-sm">VA</span>
                    )}
                  </div>
                  <h3 className="text-xl font-bold text-white mb-2 group-hover:text-emerald-400 transition-colors">
                    {srv.title}
                  </h3>
                  <p className="text-sm text-slate-400 leading-relaxed">
                    {srv.desc}
                  </p>
                </div>
                <div className="mt-6 flex items-center text-xs font-semibold text-violet-400 group-hover:text-emerald-400 space-x-1">
                  <span>Open Service</span>
                  <ArrowRight className="w-4 h-4 transition-transform group-hover:translate-x-1" />
                </div>
              </div>
            );
          })}
        </div>
      </section>

      {/* Testimonials */}
      <section className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="bg-gradient-to-br from-slate-900 via-slate-900 to-indigo-950/40 border border-slate-800 rounded-3xl p-8 sm:p-12 relative shadow-2xl">
          <div className="flex items-center justify-between mb-8">
            <div className="flex space-x-1 text-emerald-400">
              {[...Array(5)].map((_, i) => (
                <Star key={i} className="w-5 h-5 fill-emerald-400" />
              ))}
            </div>
            <div className="flex space-x-2">
              <button
                onClick={prevTestimonial}
                className="p-2 rounded-full bg-slate-800 hover:bg-slate-700 text-slate-300 transition"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <button
                onClick={nextTestimonial}
                className="p-2 rounded-full bg-slate-800 hover:bg-slate-700 text-slate-300 transition"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
          </div>

          <p className="text-lg sm:text-2xl text-slate-200 font-medium italic mb-6">
            "{TESTIMONIALS[currentTestimonial].quote}"
          </p>

          <div>
            <h4 className="text-white font-bold text-lg">{TESTIMONIALS[currentTestimonial].name}</h4>
            <p className="text-sm text-emerald-400 font-medium">{TESTIMONIALS[currentTestimonial].role}</p>
          </div>
        </div>
      </section>
    </div>
  );
}
